// ─── File: SlownessDiagnosticsDemo.java ───
// Reproduces a pool-exhaustion slowdown and prints evidence, outside-in.
// Each class below would be its own file in a real project.
package com.bank.diag;

import java.util.concurrent.*;
import java.util.logging.*;

public class SlownessDiagnosticsDemo {

    private static final Logger log = Logger.getLogger("Diag");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        log.setUseParentHandlers(false);
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        ConnectionPool pool = new ConnectionPool(5, 3000);      // 5 connections, 3s borrow timeout
        SlowQueryRepository repo = new SlowQueryRepository(pool);
        DiagnosticProbe probe = new DiagnosticProbe();

        // STEP 1 — baseline metrics BEFORE touching anything
        probe.printJvmMetrics();

        // Fire 20 concurrent "transfer" requests; each needs a connection + slow query.
        ExecutorService requests = Executors.newFixedThreadPool(20);
        for (int i = 0; i < 20; i++) {
            final int id = i;
            requests.submit(() -> {
                long start = System.currentTimeMillis();
                try {
                    repo.loadAccount(id % 2 == 0 ? "SAV2001" : "CUR3001");  // Rajesh / Priya
                    long took = System.currentTimeMillis() - start;
                    if (took > 1000) log.warning(() -> "SLOW request " + id + " took " + took + "ms");
                } catch (Exception e) {
                    log.log(Level.SEVERE, "request " + id + " failed borrowing connection", e);
                }
            });
        }

        Thread.sleep(1500);
        // STEP 2 — capture evidence WHILE it is slow (do NOT restart first!)
        probe.printThreadDumpSummary();      // thread-state histogram
        pool.printStats();                   // active vs max, waiters

        requests.shutdown();
        requests.awaitTermination(30, TimeUnit.SECONDS);
        log.info("Investigation complete: pool exhausted by a slow query → add index / fix query");
    }
}

// ─── pool/ConnectionPool.java ───  bounded pool that can be exhausted
class ConnectionPool {
    private static final Logger log = Logger.getLogger("Diag");
    private final Semaphore permits;
    private final int max;
    private final long borrowTimeoutMs;
    private volatile int active = 0, waiters = 0;

    ConnectionPool(int max, long borrowTimeoutMs) {
            this.max = max;
            this.borrowTimeoutMs = borrowTimeoutMs;
        this.permits = new Semaphore(max, true);
    }
    void borrow() throws Exception {
        waiters++;
        boolean got = permits.tryAcquire(borrowTimeoutMs, TimeUnit.MILLISECONDS);
        waiters--;
        if (!got) throw new TimeoutException("pool exhausted, no connection in " + borrowTimeoutMs + "ms");
        active++;
    }
    void release() { active--; permits.release(); }
    void printStats() {
        log.severe(() -> "POOL active=" + active + "/" + max + " waiters=" + waiters
                + "  ← active pegged at max + waiters > 0 = EXHAUSTION");
    }
}

// ─── db/SlowQueryRepository.java ───  simulates a query that lost its index
class SlowQueryRepository {
    private final ConnectionPool pool;
    SlowQueryRepository(ConnectionPool pool) { this.pool = pool; }
    void loadAccount(String id) throws Exception {
        pool.borrow();                       // hold a connection...
        try {
            Thread.sleep(800);               // ...for a long time: unindexed full scan
        } finally {
            pool.release();
        }
    }
}

// ─── probe/DiagnosticProbe.java ───  prints JVM + thread-state evidence
class DiagnosticProbe {
    private static final Logger log = Logger.getLogger("Diag");

    void printJvmMetrics() {
        Runtime rt = Runtime.getRuntime();
        long usedMb = (rt.totalMemory() - rt.freeMemory()) / (1024 * 1024);
        long maxMb = rt.maxMemory() / (1024 * 1024);
        log.info(() -> "JVM heap used=" + usedMb + "MB / max=" + maxMb + "MB, cores=" + rt.availableProcessors());
    }

    // Simplified thread dump: count threads by state (real tools: jstack / async-profiler)
    void printThreadDumpSummary() {
        java.util.Map<Thread.State, Long> byState = Thread.getAllStackTraces().keySet().stream()
                .collect(java.util.stream.Collectors.groupingBy(Thread::getState, java.util.stream.Collectors.counting()));
        log.severe(() -> "THREAD DUMP summary by state = " + byState
                + "  ← many WAITING/TIMED_WAITING on pool = starvation");
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
